  pinMode(RED, OUTPUT);
  pinMode(AMBER, OUTPUT);
  pinMode(GREEN, OUTPUT);
}

void showState(int r, int a, int g) {
  digitalWrite(RED, r);
  digitalWrite(AMBER, a);
  digitalWrite(GREEN, g);
}

void loop() {
  showState(HIGH, LOW, LOW);
  delay(3000);
  showState(HIGH, HIGH, LOW);
  delay(1000);
  showState(LOW, LOW, HIGH);
  delay(4000);
  showState(LOW, HIGH, LOW);
  delay(1000);
}

