const int LED_PIN = 9;  // PWM-capable

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  for (int brightness = 0; brightness <= 255; brightness += 5) {
    analogWrite(LED_PIN, brightness);
    delay(20);
  }
  for (int brightness = 255; brightness >= 0; brightness -= 5) {
    analogWrite(LED_PIN, brightness);
    delay(20);
  }
}

const int LDR_PIN = A0;
const int LED_PIN = 9;
const int ON_THRESHOLD = 700;
const int OFF_THRESHOLD = 620;
bool lightOn = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(LDR_PIN);
  if (!lightOn && light > ON_THRESHOLD) lightOn = true;
  if (lightOn && light < OFF_THRESHOLD) lightOn = false;
  digitalWrite(LED_PIN, lightOn ? HIGH : LOW);
  Serial.println(light);
  delay(100);
}

