const int SOIL_PIN = A0;
const int GREEN = 8;
const int AMBER = 9;
const int RED = 10;
const int DRY_THRESHOLD = 700;
const int WET_THRESHOLD = 420;

void setup() {
  Serial.begin(9600);
  pinMode(GREEN, OUTPUT);
  pinMode(AMBER, OUTPUT);
  pinMode(RED, OUTPUT);
}

void loop() {
  int soil = analogRead(SOIL_PIN);
  digitalWrite(GREEN, soil < WET_THRESHOLD);
  digitalWrite(AMBER, soil >= WET_THRESHOLD && soil < DRY_THRESHOLD);
  digitalWrite(RED, soil >= DRY_THRESHOLD);

  Serial.print(millis() / 1000);
  Serial.print("s, soil=");
  Serial.print(soil);
  Serial.print(", status=");
  Serial.println(soil < WET_THRESHOLD ? "moist" : soil < DRY_THRESHOLD ? "watch" : "dry");
  delay(2000);
}
